// 耳语总数
export const WHISPER_COUNT = adlerWhispers.length;

// 按维度索引
export const whispersByDimension: Record<string, WhisperUnit[]> = {
  A: adlerWhispers.filter(w => w.relatedDimensions?.includes('A') || w.id.startsWith('w_A_')),
  B: adlerWhispers.filter(w => w.relatedDimensions?.includes('B') || w.id.startsWith('w_B_')),
  C: adlerWhispers.filter(w => w.relatedDimensions?.includes('C') || w.id.startsWith('w_C_')),
  D: adlerWhispers.filter(w => w.relatedDimensions?.includes('D') || w.id.startsWith('w_D_')),
};

// 按场景索引
export const whispersByScene: Record<string, WhisperUnit[]> = {};
adlerWhispers.forEach(w => {
  if (w.relatedScene) {
    if (!whispersByScene[w.relatedScene]) whispersByScene[w.relatedScene] = [];
    whispersByScene[w.relatedScene].push(w);
  }
});

// 按 pair 索引
export const whispersByPair: Record<string, WhisperUnit[]> = {};
adlerWhispers.forEach(w => {
  if (w.relatedPair) {
    if (!whispersByPair[w.relatedPair]) whispersByPair[w.relatedPair] = [];
    whispersByPair[w.relatedPair].push(w);
  }
});

// 按难度选择微行动
export function getWhispersByDifficulty(
  whispers: WhisperUnit[],
  difficulty: 'gentle' | 'medium' | 'stretch',
): WhisperUnit[] {
  return whispers.filter(w => w.difficulty === difficulty);
}

// 根据 Profile 推荐耳语（混合维度 + 场景 + pair）
export function recommendWhispers(
  scores: Record<string, number>,
  scene: string,
  topPairs: string[],
  count = 5,
): WhisperUnit[] {
  const candidates: { w: WhisperUnit; score: number }[] = [];

  adlerWhispers.forEach(w => {
    let s = 0;
    if (w.relatedScene === scene) s += 3;
    if (w.relatedPair && topPairs.includes(w.relatedPair)) s += 2;
    if (w.relatedDimensions) {
      // 低分维度相关的耳语权重更高
      for (const d of w.relatedDimensions) {
        const dimScore = scores[d] || 50;
        s += (100 - dimScore) / 100;
      }
    }
    if (w.category === 'safety') s += 0.5;
    if (s > 0) candidates.push({ w, score: s });
  });

  candidates.sort((a, b) => b.score - a.score);

  // 去重 + 多样性：至少包含不同 category
  const selected: WhisperUnit[] = [];
  const seenCategories = new Set<string>();
  for (const c of candidates) {
    if (selected.length >= count) break;
    if (!seenCategories.has(c.w.category) || selected.length >= 3) {
      selected.push(c.w);
      seenCategories.add(c.w.category);
    }
  }

  // 补够数量
  if (selected.length < count) {
    for (const c of candidates) {
      if (selected.length >= count) break;
      if (!selected.includes(c.w)) {
        selected.push(c.w);
      }
    }
  }

  return selected;
}
